      "name": "Nat.le_floor_iff",
      "module_name": "Mathlib.Algebra.Order.Floor.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : Semiring α] [inst_1 : PartialOrder α] [inst_2 : FloorSemiring α] {a : α} {n : ℕ},\n  0 ≤ a → (n ≤ ⌊a⌋₊ ↔ ↑n ≤ a)"
    },
    {
      "name": "Nat.preimage_Iic",
      "module_name": "Mathlib.Algebra.Order.Floor.Semiring",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] [inst_1 : LinearOrder R] [inst_2 : FloorSemiring R] {a : R},\n  0 ≤ a → Nat.cast ⁻¹' Set.Iic a = Set.Iic ⌊a⌋₊"
    },
    {
      "name": "ENat.gc_toENNReal_floor",
