    {
      "name": "Nonneg.nat_floor_coe",
      "module_name": "Mathlib.Algebra.Order.Nonneg.Floor",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Semiring α] [inst_1 : PartialOrder α] [inst_2 : IsOrderedRing α] [inst_3 : FloorSemiring α]\n  (a : { r // 0 ≤ r }), ⌊↑a⌋₊ = ⌊a⌋₊"
    },
    {
      "name": "NNRat.floor_cast",
      "module_name": "Mathlib.Data.NNRat.Floor",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Semifield K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] [inst_3 : FloorSemiring K]\n  (x : ℚ≥0), ⌊↑x⌋₊ = ⌊x⌋₊"
    }
  ]
}
